/* Discover Sharm — service worker (app.discover-sharm.com only).  Generated by tools/build.mjs.
 *  - app shell is pre-cached, so the app opens instantly and works offline
 *  - pages: network first (always fresh), cached copy when offline, offline.html as the last resort
 *  - versioned assets (?v=hash): cache first · catalog JSON & fonts/CDN: stale-while-revalidate · photos: cache first (bounded)
 *  - API, Supabase, auth, payments and every non-GET request are never touched
 */
const VERSION = '59d94e33';
const SHELL = 'ds-shell-' + VERSION;
const RUNTIME = 'ds-runtime-v1';
const IMAGES = 'ds-images-v1';
const PRECACHE = [
  "/offline.html",
  "/manifest.webmanifest",
  "/",
  "/excursions/",
  "/transfers/",
  "/restaurants/",
  "/hotels/",
  "/about/",
  "/journal/",
  "/contact/",
  "/partner/",
  "/cancellation-policy/",
  "/refund-policy/",
  "/terms/",
  "/privacy/",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/apple-touch-icon.png",
  "/style.css?v=085d0d30",
  "/tailwind.css?v=ffd6f9de",
  "/data.js?v=1e792408",
  "/supabase-api.js?v=77e5cf3a",
  "/booking.js?v=99651b08",
  "/frontend.js?v=ea774f3c",
  "/router.js?v=daa495e0",
  "/ds-bridge.js?v=1ddb6335",
  "/ds-site.js?v=39bc7b81",
  "/pwa.js?v=bf19051b",
  "/site.css?v=e4665fd9",
  "/data/destinations.json",
  "/data/excursions.json",
  "/data/transfers.json",
  "/data/restaurants.json"
];
const CDN_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com', 'cdnjs.cloudflare.com'];
const MAX_IMAGES = 120;
const NAV_TIMEOUT = 4000;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    await Promise.allSettled(PRECACHE.map((u) => cache.add(new Request(u, { cache: 'reload' }))));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keep = [SHELL, RUNTIME, IMAGES];
    for (const k of await caches.keys()) if (k.startsWith('ds-') && !keep.includes(k)) await caches.delete(k);
    if (self.registration.navigationPreload) { try { await self.registration.navigationPreload.enable(); } catch (e) {} }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
  if (event.data === 'GET_VERSION' && event.source) event.source.postMessage({ type: 'VERSION', version: VERSION });
});

async function trimCache(name, max) {
  const cache = await caches.open(name);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - max; i++) await cache.delete(keys[i]);
}

async function networkFirstPage(event) {
  const req = event.request;
  const cache = await caches.open(RUNTIME);
  try {
    const preload = event.preloadResponse ? await event.preloadResponse : null;
    const res = preload || await Promise.race([
      fetch(req),
      new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), NAV_TIMEOUT)),
    ]);
    if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
    return res;
  } catch (e) {
    const hit = (await cache.match(req)) || (await caches.match(req)) ||
      (await caches.match(req, { ignoreSearch: true }));
    if (hit) return hit;
    return (await caches.match('/offline.html')) || Response.error();
  }
}

async function cacheFirst(req, name) {
  const hit = await caches.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res && (res.ok || res.type === 'opaque')) {
    const c = await caches.open(name);
    c.put(req, res.clone());
    if (name === IMAGES) trimCache(IMAGES, MAX_IMAGES);
  }
  return res;
}

async function staleWhileRevalidate(req, loose) {
  const cache = await caches.open(RUNTIME);
  const hit = (await cache.match(req)) || (loose ? await caches.match(req, { ignoreSearch: true }) : undefined);
  const net = fetch(req).then((res) => { if (res && (res.ok || res.type === 'opaque')) cache.put(req, res.clone()); return res; }).catch(() => null);
  return hit || (await net) || Response.error();
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('range')) return;
  const url = new URL(req.url);
  if (url.protocol !== 'https:' && url.hostname !== 'localhost') return;

  if (url.origin === self.location.origin) {
    if (url.pathname === '/sw.js' || url.pathname === '/manifest.webmanifest') return;
    if (req.mode === 'navigate') { event.respondWith(networkFirstPage(event)); return; }
    if (url.pathname.startsWith('/data/')) { event.respondWith(staleWhileRevalidate(req, true)); return; }
    if (/\.(?:css|js|png|jpe?g|webp|svg|ico|woff2?|ttf)$/i.test(url.pathname)) {
      event.respondWith(cacheFirst(req, RUNTIME));
      return;
    }
    return;
  }
  if (CDN_HOSTS.includes(url.hostname)) { event.respondWith(staleWhileRevalidate(req)); return; }
  if (req.destination === 'image') { event.respondWith(cacheFirst(req, IMAGES).catch(() => Response.error())); return; }
  // everything else (Supabase, auth, payments, analytics …) goes straight to the network
});

/* ---------- Web Push ---------- */
self.addEventListener('push', (event) => {
  let d = {};
  try { d = event.data ? event.data.json() : {}; } catch (e) { d = { body: event.data ? event.data.text() : '' }; }
  event.waitUntil(self.registration.showNotification(d.title || 'Discover Sharm', {
    body: d.body || '', icon: '/icons/icon-192.png', badge: '/icons/badge.png', tag: d.tag || undefined,
    data: { url: d.url || '/' }, lang: undefined,
  }));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = new URL((event.notification.data && event.notification.data.url) || '/', self.location.origin).href;
  event.waitUntil((async () => {
    const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const c of all) {
      if (new URL(c.url).origin === self.location.origin) { await c.focus(); if ('navigate' in c) { try { await c.navigate(url); } catch (e) {} } return; }
    }
    await self.clients.openWindow(url);
  })());
});

/* the browser rotated the push key: tell an open page so it can re-subscribe (otherwise it re-syncs on next launch) */
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil((async () => {
    for (const c of await self.clients.matchAll({ type: 'window', includeUncontrolled: true })) c.postMessage({ type: 'PUSH_RESUBSCRIBE' });
  })());
});

/* ---------- Background Sync (outbox: contact messages, reviews, unfinished booking drafts) ---------- */
function outboxDB() {
  return new Promise((res, rej) => {
    const r = indexedDB.open('ds-outbox', 1);
    r.onupgradeneeded = () => { r.result.createObjectStore('items', { keyPath: 'id' }); };
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
}
async function outboxItems() {
  try {
    const db = await outboxDB();
    return await new Promise((res) => { const q = db.transaction('items').objectStore('items').getAll(); q.onsuccess = () => res(q.result || []); q.onerror = () => res([]); });
  } catch (e) { return []; }
}
const SYNC_TXT = {
  en: ['Back online', 'Tap to finish your booking'], ar: ['رجع الاتصال', 'اضغط لإكمال حجزك'], ru: ['Связь восстановлена', 'Нажмите, чтобы завершить бронирование'],
  de: ['Wieder online', 'Tippe, um deine Buchung abzuschließen'], it: ['Di nuovo online', 'Tocca per completare la prenotazione'], tr: ['Tekrar çevrimiçi', 'Rezervasyonunuzu tamamlamak için dokunun'],
};
self.addEventListener('sync', (event) => {
  if (event.tag !== 'ds-outbox') return;
  event.waitUntil((async () => {
    const items = await outboxItems();
    if (!items.length) return;
    const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const visible = wins.some((c) => c.visibilityState === 'visible');
    wins.forEach((c) => c.postMessage({ type: 'FLUSH_OUTBOX' }));
    const draft = items.find((i) => i.kind === 'draft');
    if (draft && !visible) {
      const l = draft.lang && SYNC_TXT[draft.lang] ? draft.lang : 'en';
      await self.registration.showNotification(SYNC_TXT[l][0], { body: SYNC_TXT[l][1], icon: '/icons/icon-192.png', badge: '/icons/badge.png', tag: 'ds-draft', data: { url: '/?resume=1' } });
    }
  })());
});
